// Created: 2026-09-18

/**
 * Wiring tests for the Jev routing seam inside prompt/executor-route-nudge
 * (#4233). The seam itself is injected through `deps`, so no fetch and no
 * child process runs here; lib/route-judgment has its own suite.
 *
 * Three flag states:
 * - unset or off: the seam is never consulted and the generic reminder is
 *   byte identical to the pre-seam text
 * - shadow: the async seam is consulted, the log line lands when it settles,
 *   the reminder text does not change
 * - steer: the sync seam is consulted; at or above the floor the one nudge
 *   line names the executor; below the floor the generic reminder stays; a
 *   steered class with no ork executor produces no nudge and keeps the
 *   once-per-session flag unspent
 */

import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { HookContext, HookInput } from '../../types.js';
import { NOOP_CTX } from '../../lib/context.js';
import type { RouteVerdict } from '../../lib/route-judgment.js';
import { executorRouteNudge, type RouteSeamDeps } from '../../prompt/executor-route-nudge.js';

const BUILD_PROMPT = 'fix the flaky retry logic in the upload endpoint and add a regression test for it';

function verdict(partial: Partial<RouteVerdict>): RouteVerdict {
  return {
    decided_by: 'table',
    intent: null,
    conf: null,
    top3: [],
    worktree: null,
    browser: null,
    mutation: null,
    operator: null,
    floor: 0.5,
    latency_ms: 10,
    input_tokens: 800,
    redacted: 0,
    flag: 'steer',
    input_sha256: 'abc',
    target: null,
    error: null,
    ...partial,
  };
}

let seq = 0;
function input(prompt = BUILD_PROMPT): HookInput {
  seq += 1;
  return { tool_name: '', session_id: `jev-nudge-${seq}`, prompt_id: `prompt-${seq}`, prompt, project_dir: '/tmp/proj' } as HookInput;
}

function contextOf(result: ReturnType<typeof executorRouteNudge>): string {
  return (result.hookSpecificOutput?.additionalContext as string) || '';
}

function ctxWithLog(): { ctx: HookContext; log: ReturnType<typeof vi.fn> } {
  const log = vi.fn();
  return { ctx: { ...NOOP_CTX, projectDir: '/tmp/proj', log } as HookContext, log };
}

function deps(mode: string | undefined, overrides: Partial<RouteSeamDeps> = {}): RouteSeamDeps & { settled: Promise<void>[] } {
  const settled: Promise<void>[] = [];
  return {
    env: mode === undefined ? {} : { ORK_ROUTE_JEV: mode, ORK_TYPESAFE_API_KEY: 'k' },
    judgeAsync: vi.fn(async () => verdict({ intent: 'dev_fix', conf: 0.83, flag: 'shadow' })),
    judgeSync: vi.fn(() => verdict({ decided_by: 'jev', intent: 'dev_fix', conf: 0.83, target: { kind: 'skill', name: 'fix-issue' } })),
    track: (p) => settled.push(p),
    settled,
    ...overrides,
  };
}

let dataDir: string;
let savedPluginData: string | undefined;

beforeEach(() => {
  dataDir = mkdtempSync(join(tmpdir(), 'ork-nudge-'));
  savedPluginData = process.env.CLAUDE_PLUGIN_DATA;
  process.env.CLAUDE_PLUGIN_DATA = dataDir;
});

afterEach(() => {
  if (savedPluginData === undefined) delete process.env.CLAUDE_PLUGIN_DATA;
  else process.env.CLAUDE_PLUGIN_DATA = savedPluginData;
  rmSync(dataDir, { recursive: true, force: true });
});

const GENERIC_MARKER = 'Build-shaped goal detected. The executor skills carry the specialist wiring';

describe('executor-route-nudge with the Jev seam', () => {
  it('flag unset: never consults the seam, generic reminder unchanged', () => {
    const d = deps(undefined);
    const { ctx, log } = ctxWithLog();
    const out = contextOf(executorRouteNudge(input(), ctx, d));
    expect(out).toContain(GENERIC_MARKER);
    expect(out).not.toContain('route:');
    expect(d.judgeAsync).not.toHaveBeenCalled();
    expect(d.judgeSync).not.toHaveBeenCalled();
    expect(log).not.toHaveBeenCalled();
  });

  it('flag off: same as unset', () => {
    const d = deps('off');
    const out = contextOf(executorRouteNudge(input(), ctxWithLog().ctx, d));
    expect(out).toContain(GENERIC_MARKER);
    expect(d.judgeAsync).not.toHaveBeenCalled();
    expect(d.judgeSync).not.toHaveBeenCalled();
  });

  it('shadow: consults the async seam, injects the generic reminder, logs the route line on settle', async () => {
    const d = deps('shadow');
    const { ctx, log } = ctxWithLog();
    const out = contextOf(executorRouteNudge(input(), ctx, d));
    expect(out).toContain(GENERIC_MARKER);
    expect(out).not.toContain('route:');
    expect(d.judgeAsync).toHaveBeenCalledTimes(1);
    expect(d.judgeSync).not.toHaveBeenCalled();
    const opts = (d.judgeAsync as ReturnType<typeof vi.fn>).mock.calls[0][0];
    expect(opts.prompt).toBe(BUILD_PROMPT);
    expect(opts.promptId).toBe(`prompt-${seq}`);
    expect(opts.projectDir).toBe('/tmp/proj');
    await Promise.all(d.settled);
    expect(log).toHaveBeenCalledWith(
      'executor-route-nudge',
      expect.stringMatching(/^route jev: jev_pick=skill:ork:fix-issue jev_confidence=0\.83 .*agree=null .*floor=0\.5 decided_by=table .*redacted=0$/),
    );
  });

  it('shadow: the seam is consulted on every build-shaped prompt, the nudge only once', async () => {
    const d = deps('shadow');
    const sessionId = 'jev-nudge-shadow-twice';
    const first = executorRouteNudge({ ...input(), session_id: sessionId }, ctxWithLog().ctx, d);
    const second = executorRouteNudge({ ...input(), session_id: sessionId }, ctxWithLog().ctx, d);
    expect(contextOf(first)).not.toBe('');
    expect(contextOf(second)).toBe('');
    expect(d.judgeAsync).toHaveBeenCalledTimes(2);
    await Promise.all(d.settled);
  });

  it('shadow: a non build-shaped prompt never reaches the seam', () => {
    const d = deps('shadow');
    executorRouteNudge(input('ok'), ctxWithLog().ctx, d);
    executorRouteNudge(input('explain how the retry logic in the upload endpoint decides to give up'), ctxWithLog().ctx, d);
    expect(d.judgeAsync).not.toHaveBeenCalled();
  });

  it('steer above the floor: the one line names the executor', () => {
    const d = deps('steer');
    const { ctx, log } = ctxWithLog();
    const out = contextOf(executorRouteNudge(input(), ctx, d));
    expect(out).toContain('route: dev_fix -> /ork:fix-issue (conf 0.83)');
    expect(out).not.toContain(GENERIC_MARKER);
    expect(d.judgeSync).toHaveBeenCalledTimes(1);
    expect(d.judgeAsync).not.toHaveBeenCalled();
    expect(log).toHaveBeenCalledWith('executor-route-nudge', expect.stringContaining('decided_by=jev'));
  });

  it('steer below the floor: the generic reminder stays', () => {
    const d = deps('steer', {
      judgeSync: vi.fn(() => verdict({ decided_by: 'table', intent: 'dev_fix', conf: 0.31, target: { kind: 'skill', name: 'fix-issue' } })),
    });
    const out = contextOf(executorRouteNudge(input(), ctxWithLog().ctx, d));
    expect(out).toContain(GENERIC_MARKER);
    expect(out).not.toContain('route:');
  });

  it('steer with a dead lane: the generic reminder stays', () => {
    const d = deps('steer', { judgeSync: vi.fn(() => verdict({ decided_by: 'table', error: 'timeout' })) });
    const out = contextOf(executorRouteNudge(input(), ctxWithLog().ctx, d));
    expect(out).toContain(GENERIC_MARKER);
  });

  it('steer to an ops class: no nudge at all, and the once flag stays unspent', () => {
    const sessionId = 'jev-nudge-ops';
    const ops = deps('steer', { judgeSync: vi.fn(() => verdict({ decided_by: 'jev', intent: 'ops_deploy', conf: 0.9, target: null })) });
    const silent = executorRouteNudge({ ...input(), session_id: sessionId }, ctxWithLog().ctx, ops);
    expect(contextOf(silent)).toBe('');
    // the next build-shaped prompt in the same session can still nudge
    const dev = deps('steer');
    const later = executorRouteNudge({ ...input(), session_id: sessionId }, ctxWithLog().ctx, dev);
    expect(contextOf(later)).toContain('route: dev_fix -> /ork:fix-issue');
  });

  it('steer names an agent target the same way', () => {
    const d = deps('steer', {
      judgeSync: vi.fn(() => verdict({ decided_by: 'jev', intent: 'research', conf: 0.77, target: { kind: 'agent', name: 'Explore' } })),
    });
    const out = contextOf(executorRouteNudge(input('build me a summary of how other teams handle retry budgets'), ctxWithLog().ctx, d));
    expect(out).toContain('route: research -> Agent(Explore) (conf 0.77)');
    expect(out).toContain('spawn it via the Agent tool');
    expect(out).not.toContain('via the Skill tool');
  });
});
